window.AUTH=window.AUTH||{};window.AUTH["25-183"]={"d":"25-183","id":"2026/25-183","n":"Crowther v. Board of Regents of the University System of Georgia","briefs":[{"k":"petitioner","label":"Brief of petitioners Thomas Crowther, et al.","date":"2026-07-10","url":"https://www.supremecourt.gov/DocketPDF/25/25-183/416255/20260710170938887_25-183%20Brief%20for%20Petitioner.pdf","side":"pet","n":63},{"k":"respondent","label":"Brief of respondents Board of Regents of the University System of Georgia, et al.","date":"2026-08-17","url":"https://www.supremecourt.gov/DocketPDF/25/25-183/419316/20260817172815816_25-183%20Brief.pdf","side":"res","n":111},{"k":"united-states","label":"Brief amicus curiae of United States in support of respondents","date":"2026-08-24","url":"https://www.supremecourt.gov/DocketPDF/25/25-183/419972/20260824155803178_25-183_Crowther_bsac.pdf","side":"res","n":94},{"k":"reply","label":"Reply of petitioners Thomas Crowther, et al.","date":"2026-09-16","url":"https://www.supremecourt.gov/DocketPDF/25/25-183/424604/20260916183211139_25-183%20Reply%20Brief.pdf","side":"pet","n":35}],"opinion":null,"tr":false,"items":[{"t":"case","label":"Alexander v. Gardner-Denver Co.","cite":"415 U.S. 36","y":1974,"id":"1973/72-5847","sc":1,"sum":"An employee's statutory right to trial de novo under Title VII of the Civil Rights Act of 1964 is not foreclosed by prior submission of his claim to final arbitration under the nondiscrimination clause of a collective-bargaining.agreement.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49","1":"25","2":"25","3":"21"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"3, 4, 10, 19, 20, 23, 24, 32, 36, 41, 43, 44, 47, 50, 53","1":"1, 2, 12, 14-17, 19, 22, 26, 28-31, 33, 35, 41-44, 47","2":"12-15, 17, 25, 27, 29, 31","3":"1, 4, 5, 6, 10, 17"}},{"t":"case","label":"Barnes v. Gorman","cite":"536 U.S. 181","y":2002,"id":"2001/01-682","sc":1,"sum":"The Court held that, because punitive damages may not be awarded in private suits brought under Title VI of the 1964 Civil Rights Act, it follows that they may not be awarded in suits brought under the ADA and the Rehabilitation Act.","sumSrc":"Oyez","by":{"0":"5, 26, 36, 40, 48, 57","1":"5, 20","2":"26"}},{"t":"case","label":"Bennett v. Ky. Dep’t of Educ.","cite":"470 U.S. 656","y":1985,"id":"1984/83-1798","sc":1,"sum":"The Secretary properly determined that Kentucky violated its assurances of compliance with Title I requirements by approving the \"readiness classes\" and thereby misused Title I funds.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"56"}},{"t":"case","label":"Cannon v. Univ. of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 6, 7, 8, 22, 23, 30, 33, 53","1":"4, 5, 8, 13, 14, 21, 30-32, 38, 42, 44","2":"2, 7, 11, 12, 21","3":"5, 16, 19"}},{"t":"case","label":"CBOCS W., Inc. v. Humphries","cite":"553 U.S. 442","y":2008,"id":"2007/06-1431","sc":1,"sum":"Section 1981 encompasses retaliation claims. The 7-2 decision, written by Justice Stephen Breyer, relied heavily on the concept of stare decisis, or adherence to prior Court decisions, in reaching its conclusion.","sumSrc":"Oyez","by":{"0":"46, 48, 49","1":"25","2":"25","3":"9, 20, 21, 22, 24"}},{"t":"case","label":"Consol. Rail Corp. v. Darrone","cite":"465 U.S. 624","y":1984,"id":"1983/82-862","sc":1,"sum":"Section 504 of the Rehabilitation Act of 1973 provides that \"[n]o... handicapped individual... shall, solely by reason of his handicap,... be subjected to discrimination under any program or activity receiving Federal financial assistance.\" Section 505(a)(2), which was added to the Act in 1978, makes \"available\" the \"remedies, procedures, and rights\" set forth in Title VI of the Civil Rights Act of 1964 (Title VI) …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36, 39, 40, 42","1":"40, 46","2":"27","3":"16"}},{"t":"case","label":"Cummings v. Premier Rehab Keller, P.L.L.C.","cite":"596 U.S. 212","y":2022,"id":"2021/20-219","sc":1,"sum":"Emotional distress damages are not recoverable in a private action to enforce either the Rehabilitation Act of 1973 or the Affordable Care Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23, 24, 35, 36, 44, 48, 55, 57","1":"13, 19, 20, 47","2":"3, 7, 13, 14, 26","3":"5, 6, 26"}},{"t":"case","label":"Davis v. Monroe Cnty. Bd. of Educ.","cite":"526 U.S. 629","y":1999,"id":"1998/97-843","sc":1,"sum":"The Court held that a school board can be liable for student-on-student harassment if the board acts with deliberate indifference.","sumSrc":"Oyez","by":{"0":"7, 11, 26, 28, 56","1":"3, 21, 28, 36","2":"3, 16, 32","3":"7, 8, 16, 26"}},{"t":"case","label":"Doe v. Prairie View A&M Univ.","cite":"2018 WL 1947804","y":2018,"court":"S.D. Tex. Apr. 25","by":{"0":"51"}},{"t":"case","label":"Fitzgerald v. Barnstable Sch. Comm.","cite":"555 U.S. 246","y":2009,"id":"2008/07-1125","sc":1,"sum":"The Court found that a claim filed under Title IX for violation of the Equal Protection Clause of the fourteenth Amendment does not preclude the use of 42 U.S.C. Section 1983 which protects against the deprivation of any rights guaranteed by the Constitution and federal law.","sumSrc":"Oyez","by":{"0":"38, 40, 48","1":"27","2":"7"}},{"t":"case","label":"Forest Grove Sch. Dist. v. T.A.","cite":"557 U.S. 230","y":2009,"id":"2008/08-305","sc":1,"sum":"The Court found that the Individuals with Disabilities Education Act (IDEA) can authorize a public school to reimburse a student for private school tuition sought because the student never received special education services at the public school.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Franklin v. Gwinnett Cnty. Pub. Schs.","cite":"503 U.S. 60","y":1992,"id":"1991/90-918","sc":1,"sum":"Justice Byron R. White wrote the Court's unanimous decision, holding that monetary damages are available under Title IX because there is a presumption that any appropriate relief is available to remedy the violation of a federal right. In this case, back pay and prospective relief were not sufficient remedies.","sumSrc":"Oyez","by":{"0":"3, 4, 9, 10, 11, 23, 24, 26, 27, 35, 36, 39, 43, 44, 53, 56","1":"7, 23","2":"14, 29","3":"3, 5, 7, 11, 16, 17"}},{"t":"case","label":"Gebser v. Lago Vista Indep. Sch. Dist.","cite":"524 U.S. 274","y":1998,"id":"1997/96-1866","sc":1,"sum":"In a 5-to-4 decision the Court held that two minimal criteria must be met in order for an aggrieved party to recover sexual harassment damages under the Amendments. First, the party must show that a school district official, with the ability to institute corrective measures, knew of the forbidden conduct.","sumSrc":"Oyez","by":{"0":"11, 23, 25, 47","1":"7, 8, 19, 21, 28, 30","2":"2, 5, 10, 15-18, 27","3":"6, 7, 8"}},{"t":"case","label":"Gomez-Perez v. Potter","cite":"553 U.S. 474","y":2008,"id":"2007/06-1321","sc":1,"sum":"Noting the similarity between these statutes and the ADEA, Alito concluded that Congress had intended to include a retaliation prohibition in the ADEA. Chief Justice John G. Roberts and Justice Clarence Thomas filed dissenting opinions each joined in part by Justice Antonin Scalia.","sumSrc":"Oyez","by":{"0":"25","1":"4, 16, 22, 26, 37, 38","2":"21","3":"9, 10, 17"}},{"t":"case","label":"Grove City Coll. v. Bell","cite":"465 U.S. 555","y":1984,"id":"1983/82-792","sc":1,"sum":"The Court held that there was no \"substantive difference\" between institutional assistance and aid received by a school through its students; Title IX coverage, the Court found, was triggered by the BEOG's. The Court noted that the assistance did not trigger institutionwide coverage under the Amendments, however. Only the College's financial aid program was subject to the federal requirements.","sumSrc":"Oyez","by":{"0":"10, 44"}},{"t":"case","label":"Guardians Ass’n v. Civ. Serv. Comm’n of N.Y.C.","cite":"463 U.S. 582","y":1983,"id":"1982/81-431","sc":1,"sum":"The judgment is affirmed. 633 F. 2d 232, affirmed. JUSTICE WHITE concluded that discriminatory intent is not an essential element of a Title VI violation. JUSTICE WHITE, joined by JUSTICE REHNQUIST, also concluded that a private plaintiff should recover only injunctive, noncompensatory relief for a defendant's unintentional violation of Title VI, that such relief should not include an award of constructive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36, 40, 42","1":"5, 28, 41, 44, 46","2":"27","3":"16, 22"}},{"t":"case","label":"HUD v. Rucker","cite":"535 U.S. 125","y":2002,"id":"2001/00-1770","sc":1,"sum":"The Court held that the Anti-Drug Abuse Act of 1988 unambiguously requires lease terms that vest local public housing authorities with the discretion to evict tenants for the drug-related activity of household members and guests whether or not the tenant knew, or should have known, about the activity.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Jackson v. Birmingham Bd. of Educ.","cite":"544 U.S. 167","y":2005,"id":"2004/02-1672","sc":1,"sum":"The Court held that Title IX allowed suits alleging retaliation for reporting sex discrimination. Such retaliation, the majority reasoned, constituted intentional discrimination on the basis of sex in violation of Title IX. Jackson therefore had the right under Title IX to pursue his claim in court.","sumSrc":"Oyez","by":{"0":"3, 4, 5, 6, 7, 8, 11, 19, 20, 22, 23, 25, 27, 28, 30, 31, 33, 34, 35, 46, 47, 53, 54, 55, 56","1":"4, 8, 11, 13, 14, 21, 29, 33-38, 47, 48","2":"3, 7, 11, 20, 22, 23, 32","3":"19, 21"}},{"t":"case","label":"Johnson v. Ry. Express Agency, Inc.","cite":"421 U.S. 454","y":1975,"id":"1974/73-1543","sc":1,"sum":"The timely filing of an employment discrimination charge with the Equal Employment Opportunity Commission, pursuant to § 706 of Title VII of the Civil Rights Act of 1964, does not toll the running of the limitation period applicable to an action, based on the same facts, brought under 42 U. S. C. § 1981. Thus, in this case where petitioner waited over 31/2 years after his cause of action for racial employment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48, 49, 50","1":"25","2":"3, 23, 25"}},{"t":"case","label":"Johnson v. Transp. Agency","cite":"480 U.S. 616","y":1987,"id":"1986/85-1129","sc":1,"sum":"The Court affirmed the promotion procedures of the Agency. Justice Brennan argued that it was not unreasonable to consider sex as one factor among many in making promotion decisions, and that the Agency's actions did not create an absolute barrier to the advancement of men (a quota system did not exist).","sumSrc":"Oyez","by":{"0":"50"}},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"32"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"sum":"Yes. Although the ADEA does not expressly provide for jury trials, its structure shows that Congress intended a jury to be available in private ADEA actions when a party seeks one. The Court therefore did not reach the Seventh Amendment question.","sumSrc":"AI-generated brief","by":{"0":"41"}},{"t":"case","label":"Minor v. Northville Pub. Schs.","cite":"605 F. Supp. 1185","y":1985,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp./605/1185/","by":{"0":"42","1":"40","2":"28"}},{"t":"case","label":"North Haven Bd. of Educ. v. Bell","cite":"456 U.S. 512","y":1982,"id":"1981/80-986","sc":1,"sum":"The Court held that, while Title IX does not expressly include employees, Congress’s choice of words, i.e. “no person” as opposed to “student” or “beneficiary”, implies an intention to broadly cover individuals involved in educational institutions rather than only students.","sumSrc":"Oyez","by":{"0":"3, 6, 9, 19, 20, 27, 28, 29, 31, 32, 37, 38, 42, 45, 46, 49, 50","1":"3, 13, 22, 26-28, 32, 33, 37, 39, 40, 45, 46","2":"3, 7, 11, 18, 21, 30","3":"2, 3, 12, 13, 14, 15, 16, 18, 19, 20, 24, 27"}},{"t":"case","label":"O’Connor v. Peru State Coll.","cite":"781 F.2d 632","y":1986,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/781/632/","sum":"Stating, in a footnote, that an employee had “standing” to bring a Title IX claim.","sumSrc":"brief:2","by":{"0":"42","1":"40","2":"28"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"451 U.S. 1","y":1981,"id":"1980/79-1404","sc":1,"sum":"Section 6010 does not create in favor of the mentally retarded any substantive rights to \"appropriate treatment\" in the \"least restrictive\" environment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 55"}},{"t":"case","label":"POM Wonderful LLC v. Coca-Cola Co.","cite":"573 U.S. 102","y":2014,"id":"2013/12-761","sc":1,"sum":"The Court held that it is the duty of the court system to harmonize statutes, and that barring one applicable statute by use of another represents a disregard of the law's intent of having cooperative statutes.","sumSrc":"Oyez","by":{"0":"17, 50","3":"24, 29"}},{"t":"case","label":"Rivers v. Roadway Express, Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"sum":"Section 101 does not apply to a case that arose before it was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"54"}},{"t":"case","label":"Saffer v. Town of Whitman","cite":"1986 WL 14090","y":1986,"court":"D. Mass. Dec. 2","by":{"0":"42","2":"28"}},{"t":"case","label":"Selzer v. Bd. of Educ. of N.Y.C.","cite":"112 F.R.D. 176","y":1986,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.R.D./112/176/","by":{"0":"43","1":"40"}},{"t":"case","label":"Texas Dep’t of Hous. & Cmty. Affs. v. Inclusive Comtys. Project, Inc.","cite":"576 U.S. 519","y":2015,"id":"2014/13-1371","sc":1,"sum":"The Court determined that evidence of disparate impact is sufficient to allege a claim that the defendant violated the Fair Housing Act.","sumSrc":"Oyez","by":{"0":"41, 44, 50"}},{"t":"case","label":"United States v. Morrow","cite":"266 U.S. 531","y":1925,"id":"scdb/1924-070","sc":1,"sum":"Mr, Merrill E. Otis, Special Assistant to the Attorney General, with whom Mr. Solicitor General Beck and Mr. John G. Ewing were on the brief, /or the Ünited States.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Univ. of Texas Sw. Med. Ctr. v. Nassar","cite":"570 U.S. 338","y":2013,"id":"2012/12-484","sc":1,"sum":"The Court found that Title VII of the Civil Rights Act of 1964 requires the plaintiff to prove their employer would not have taken an action but for the existence of improper motives.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Vance v. Ball State Univ.","cite":"570 U.S. 421","y":2013,"id":"2012/11-556","sc":1,"sum":"The Court held that, for purposes of liability for workplace harassment, the definition of \"supervisor\" is limited to a person empowered to take tangible employment action against the victim.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"West Virginia v. B.P.J.","cite":"609 U.S. __","y":2026,"id":"2025/24-43","sc":1,"sum":"Title IX allows schools to provide separate women’s and men’s sports teams defined by biological sex; West Virginia and Idaho did not violate the Equal Protection Clause of the Fourteenth Amendment by maintaining female sports teams for biological females.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"3, 6, 7, 32, 47","2":"4"}},{"t":"usc","label":"20 U.S.C. § 1682","url":"https://www.law.cornell.edu/uscode/text/20/1682","stext":{"head":"§1682. Federal administrative enforcement; report to Congressional committees","paras":[[0,"Each Federal department and agency which is empowered to extend Federal financial assistance to any education program or activity, by way of grant, loan, or contract other than a contract of insurance or guaranty, is authorized and directed to effectuate the provisions of section 1681 of this title with respect to such program or activity by issuing rules, regulations, or orders of general applicability which shall be consistent with achievement of the objectives of the statute authorizing the financial assistance in connection with which the action is taken. No such rule, regulation, or order shall become effective unless and until approved by the President. Compliance with any requirement adopted pursuant to this section may be effected (1) by the termination of or refusal to grant or to continue assistance under such program or activity to any recipient as to whom there has been an express finding on the record, after opportunity for hearing, of a failure to comply with such requirement, but such termination or refusal shall be limited to the particular political entity, or part thereof, or other recipient as to whom such a finding has been made, and shall be limited in its effect to the particular program, or part thereof, in which such noncompliance has been so found, or (2) by any other means authorized by law: Provided, however, That no such action shall be taken until the department or agency concerned has advised the appropriate person or persons of the failure to comply with the requirement and has determined that compliance cannot be secured by voluntary means. In the case of any action terminating, or refusing to grant or continue, assistance because of failure to comply with a requirement imposed pursuant to this section, the head of the Federal department or agency shall file with the committees of the House and Senate having legislative jurisdiction over the program or activity involved a full written report of the circumstances and the grounds for such action. No such action shall become effective until thirty days have elapsed after the filing of such report."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/20/1682?type=usc&year=mostrecent&link-type=html"},"head":"§1682. Federal administrative enforcement; report to Congressional committees","tname":"Education","by":{"0":"32","1":"8, 36","2":"7, 16"}},{"t":"usc","label":"20 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/20/1681","subs":["(a)"],"stext":{"head":"§1681. Sex","paras":[[0,"(a) Prohibition against discrimination; exceptions"],[0,"No person in the United States shall, on the basis of sex, be excluded from participation in, be denied the benefits of, or be subjected to discrimination under any education program or activity receiving Federal financial assistance, except that:"],[0,"(1) Classes of educational institutions subject to prohibition"],[1,"in regard to admissions to educational institutions, this section shall apply only to institutions of vocational education, professional education, and graduate higher education, and to public institutions of undergraduate higher education;"],[0,"(2) Educational institutions commencing planned change in admissions"],[1,"in regard to admissions to educational institutions, this section shall not apply (A) for one year from June 23, 1972, nor for six years after June 23, 1972, in the case of an educational institution which has begun the process of changing from being an institution which admits only students of one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education or (B) for seven years from the date an educational institution begins the process of changing from being an institution which admits only students of only one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education, whichever is the later;"],[0,"(3) Educational institutions of religious organizations with contrary religious tenets"],[1,"this section shall not apply to an educational institution which is controlled by a religious organization if the application of this subsection would not be consistent with the religious tenets of such organization;"],[0,"(4) Educational institutions training individuals for military services or merchant marine"],[1,"this section shall not apply to an educational institution whose primary purpose is the training of individuals for the military services of the United States, or the merchant marine;"],[0,"(5) Public educational institutions with traditional and continuing admissions policy"],[1,"in regard to admissions this section shall not apply to any public institution of undergraduate higher education which is an institution that traditionally and continually from its establishment has had a policy of admitting only students of one sex;"],[0,"(6) Social fraternities or sororities; voluntary youth service organizations"],[1,"this section shall not apply to membership practices—"],[2,"(A) of a social fraternity or social sorority which is exempt from taxation under section 501(a) of title 26, the active membership of which consists primarily of students in attendance at an institution of higher education, or"],[2,"(B) of the Young Men's Christian Association, Young Women's Christian Association, Girl Scouts, Boy Scouts, Camp Fire Girls, and voluntary youth service organizations which are so exempt, the membership of which has traditionally been limited to persons of one sex and principally to persons of less than nineteen years of age;"],[0,"(7) Boy or Girl conferences"],[1,"this section shall not apply to—"],[2,"(A) any program or activity of the American Legion undertaken in connection with the organization or operation of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[2,"(B) any program or activity of any secondary school or educational institution specifically for—"],[3,"(i) the promotion of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[3,"(ii) the selection of students to attend any such conference;"],[0,"(8) Father-son or mother-daughter activities at educational institutions"],[1,"this section shall not preclude father-son or mother-daughter activities at an educational institution, but if such activities are provided for students of one sex, opportunities for reasonably comparable activities shall be provided for students of the other sex; and"],[0,"(9) Institution of higher education scholarship awards in \"beauty\" pageants"],[1,"this section shall not apply with respect to any scholarship or other financial assistance awarded by an institution of higher education to any individual because such individual has received such award in any pageant in which the attainment of such award is based upon a combination of factors related to the personal appearance, poise, and talent of such individual and in which participation is limited to individuals of one sex only, so long as such pageant is in compliance with other nondiscrimination provisions of Federal law."],[0,"(b) Preferential or disparate treatment because of imbalance in participation or receipt of Federal benefits; statistical evidence of imbalance"],[0,"Nothing contained in subsection (a) of this section shall be interpreted to require any educational institution to grant preferential or disparate treatment to the members of one sex on account of an imbalance which may exist with respect to the total number or percentage of persons of that sex participating in or receiving the benefits of any federally supported program or activity, in comparison with the total number or percentage of persons of that sex in any community, State, section, or other area: Provided, That this subsection shall not be construed to prevent the consideration in any hearing or proceeding under this chapter of statistical evidence tending to show that such an imbalance exists with respect to the participation in, or receipt of the benefits of, any such program or activity by the members of one sex."],[0,"(c) \"Educational institution\" defined"],[0,"For purposes of this chapter an educational institution means any public or private preschool, elementary, or secondary school, or any institution of vocational, professional, or higher education, except that in the case of an educational institution composed of more than one school, college, or department which are administratively separate units, such term means each such school, college, or department."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/20/1681?type=usc&year=mostrecent&link-type=html"},"head":"§1681. Sex","tname":"Education","by":{"0":"2, 3, 4, 8, 20, 25, 27, 28, 30, 34, 37, 47, 50","1":"8, 22","2":"1, 6, 6, 18","3":"2"}},{"t":"usc","label":"29 U.S.C. § 794","url":"https://www.law.cornell.edu/uscode/text/29/794","subs":["(a)"],"stext":{"head":"§794. Nondiscrimination under Federal grants and programs","paras":[[0,"(a) Promulgation of rules and regulations"],[0,"No otherwise qualified individual with a disability in the United States, as defined in section 705(20) of this title, shall, solely by reason of her or his disability, be excluded from the participation in, be denied the benefits of, or be subjected to discrimination under any program or activity receiving Federal financial assistance or under any program or activity conducted by any Executive agency or by the United States Postal Service. The head of each such agency shall promulgate such regulations as may be necessary to carry out the amendments to this section made by the Rehabilitation, Comprehensive Services, and Developmental Disabilities Act of 1978. Copies of any proposed regulation shall be submitted to appropriate authorizing committees of the Congress, and such regulation may take effect no earlier than the thirtieth day after the date on which such regulation is so submitted to such committees."],[0,"(b) \"Program or activity\" defined"],[0,"For the purposes of this section, the term \"program or activity\" means all of the operations of—"],[1,"(1)(A) a department, agency, special purpose district, or other instrumentality of a State or of a local government; or"],[1,"(B) the entity of such State or local government that distributes such assistance and each such department or agency (and each other State or local government entity) to which the assistance is extended, in the case of assistance to a State or local government;"],[1,"(2)(A) a college, university, or other postsecondary institution, or a public system of higher education; or"],[1,"(B) a local educational agency (as defined in section 7801 of title 20), system of career and technical education, or other school system;"],[1,"(3)(A) an entire corporation, partnership, or other private organization, or an entire sole proprietorship—"],[2,"(i) if assistance is extended to such corporation, partnership, private organization, or sole proprietorship as a whole; or"],[2,"(ii) which is principally engaged in the business of providing education, health care, housing, social services, or parks and recreation; or"],[1,"(B) the entire plant or other comparable, geographically separate facility to which Federal financial assistance is extended, in the case of any other corporation, partnership, private organization, or sole proprietorship; or"],[1,"(4) any other entity which is established by two or more of the entities described in paragraph (1), (2), or (3);"],[0,"any part of which is extended Federal financial assistance."],[0,"(c) Significant structural alterations by small providers"],[0,"Small providers are not required by subsection (a) to make significant structural alterations to their existing facilities for the purpose of assuring program accessibility, if alternative means of providing the services are available. The terms used in this subsection shall be construed with reference to the regulations existing on March 22, 1988."],[0,"(d) Standards used in determining violation of section"],[0,"The standards used to determine whether this section has been violated in a complaint alleging employment discrimination under this section shall be the standards applied under title I of the Americans with Disabilities Act of 1990 (42 U.S.C. 12111 et seq.) and the provisions of sections 501 through 504, and 510,1 of the Americans with Disabilities Act of 1990 (42 U.S.C. 12201–12204 and 12210), as such sections relate to employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/794?type=usc&year=mostrecent&link-type=html"},"head":"§794. Nondiscrimination under Federal grants and programs","tname":"Labor","by":{"0":"20, 35, 39","2":"28"}},{"t":"usc","label":"42 U.S.C. § 1981a","url":"https://www.law.cornell.edu/uscode/text/42/1981a","stext":{"head":"§1981a. Damages in cases of intentional discrimination in employment","paras":[[0,"(a) Right of recovery"],[0,"(1) Civil rights"],[1,"In an action brought by a complaining party under section 706 or 717 of the Civil Rights Act of 1964 [42 U.S.C. 2000e–5, 2000e–16] against a respondent who engaged in unlawful intentional discrimination (not an employment practice that is unlawful because of its disparate impact) prohibited under section 703, 704, or 717 of the Act [42 U.S.C. 2000e–2, 2000e–3, 2000e–16], and provided that the complaining party cannot recover under section 1981 of this title, the complaining party may recover compensatory and punitive damages as allowed in subsection (b), in addition to any relief authorized by section 706(g) of the Civil Rights Act of 1964, from the respondent."],[0,"(2) Disability"],[1,"In an action brought by a complaining party under the powers, remedies, and procedures set forth in section 706 or 717 of the Civil Rights Act of 1964 [42 U.S.C. 2000e–5, 2000e–16] (as provided in section 107(a) of the Americans with Disabilities Act of 1990 (42 U.S.C. 12117(a)), and section 794a(a)(1) of title 29, respectively) against a respondent who engaged in unlawful intentional discrimination (not an employment practice that is unlawful because of its disparate impact) under section 791 of title 29 and the regulations implementing section 791 of title 29, or who violated the requirements of section 791 of title 29 or the regulations implementing section 791 of title 29 concerning the provision of a reasonable accommodation, or section 102 of the Americans with Disabilities Act of 1990 (42 U.S.C. 12112), or committed a violation of section 102(b)(5) of the Act, against an individual, the complaining party may recover compensatory and punitive damages as allowed in subsection (b), in addition to any relief authorized by section 706(g) of the Civil Rights Act of 1964, from the respondent."],[0,"(3) Reasonable accommodation and good faith effort"],[1,"In cases where a discriminatory practice involves the provision of a reasonable accommodation pursuant to section 102(b)(5) of the Americans with Disabilities Act of 1990 [42 U.S.C. 12112(b)(5)] or regulations implementing section 791 of title 29, damages may not be awarded under this section where the covered entity demonstrates good faith efforts, in consultation with the person with the disability who has informed the covered entity that accommodation is needed, to identify and make a reasonable accommodation that would provide such individual with an equally effective opportunity and would not cause an undue hardship on the operation of the business."],[0,"(b) Compensatory and punitive damages"],[0,"(1) Determination of punitive damages"],[1,"A complaining party may recover punitive damages under this section against a respondent (other than a government, government agency or political subdivision) if the complaining party demonstrates that the respondent engaged in a discriminatory practice or discriminatory practices with malice or with reckless indifference to the federally protected rights of an aggrieved individual."],[0,"(2) Exclusions from compensatory damages"],[1,"Compensatory damages awarded under this section shall not include backpay, interest on backpay, or any other type of relief authorized under section 706(g) of the Civil Rights Act of 1964 [42 U.S.C. 2000e–5(g)]."],[0,"(3) Limitations"],[1,"The sum of the amount of compensatory damages awarded under this section for future pecuniary losses, emotional pain, suffering, inconvenience, mental anguish, loss of enjoyment of life, and other nonpecuniary losses, and the amount of punitive damages awarded under this section, shall not exceed, for each complaining party—"],[2,"(A) in the case of a respondent who has more than 14 and fewer than 101 employees in each of 20 or more calendar weeks in the current or preceding calendar year, $50,000;"],[2,"(B) in the case of a respondent who has more than 100 and fewer than 201 employees in each of 20 or more calendar weeks in the current or preceding calendar year, $100,000; and"],[2,"(C) in the case of a respondent who has more than 200 and fewer than 501 employees in each of 20 or more calendar weeks in the current or preceding calendar year, $200,000; and"],[2,"(D) in the case of a respondent who has more than 500 employees in each of 20 or more calendar weeks in the current or preceding calendar year, $300,000."],[0,"(4) Construction"],[1,"Nothing in this section shall be construed to limit the scope of, or the relief available under, section 1981 of this title."],[0,"(c) Jury trial"],[0,"If a complaining party seeks compensatory or punitive damages under this section—"],[1,"(1) any party may demand a trial by jury; and"],[1,"(2) the court shall not inform the jury of the limitations described in subsection (b)(3)."],[0,"(d) Definitions"],[0,"As used in this section:"],[0,"(1) Complaining party"],[1,"The term \"complaining party\" means—"],[2,"(A) in the case of a person seeking to bring an action under subsection (a)(1), the Equal Employment Opportunity Commission, the Attorney General, or a person who may bring an action or proceeding under title VII of the Civil Rights Act of 1964 (42 U.S.C. 2000e et seq.); or"],[2,"(B) in the case of a person seeking to bring an action under subsection (a)(2), the Equal Employment Opportunity Commission, the Attorney General, a person who may bring an action or proceeding under section 794a(a)(1) of title 29, or a person who may bring an action or proceeding under title I of the Americans with Disabilities Act of 1990 [42 U.S.C. 12111 et seq.]."],[0,"(2) Discriminatory practice"],[1,"The term \"discriminatory practice\" means the discrimination described in paragraph (1), or the discrimination or the violation described in paragraph (2), of subsection (a)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1981a?type=usc&year=mostrecent&link-type=html"},"head":"§1981a. Damages in cases of intentional discrimination in employment","tname":"The Public Health and Welfare","by":{"0":"48","1":"7","2":"5"}},{"t":"usc","label":"42 U.S.C. § 1988","url":"https://www.law.cornell.edu/uscode/text/42/1988","stext":{"head":"§1988. Proceedings in vindication of civil rights","paras":[[0,"(a) Applicability of statutory and common law"],[0,"The jurisdiction in civil and criminal matters conferred on the district courts by the provisions of titles 13, 24, and 70 of the Revised Statutes for the protection of all persons in the United States in their civil rights, and for their vindication, shall be exercised and enforced in conformity with the laws of the United States, so far as such laws are suitable to carry the same into effect; but in all cases where they are not adapted to the object, or are deficient in the provisions necessary to furnish suitable remedies and punish offenses against law, the common law, as modified and changed by the constitution and statutes of the State wherein the court having jurisdiction of such civil or criminal cause is held, so far as the same is not inconsistent with the Constitution and laws of the United States, shall be extended to and govern the said courts in the trial and disposition of the cause, and, if it is of a criminal nature, in the infliction of punishment on the party found guilty."],[0,"(b) Attorney's fees"],[0,"In any action or proceeding to enforce a provision of sections 1981, 1981a, 1982, 1983, 1985, and 1986 of this title, title IX of Public Law 92–318 [20 U.S.C. 1681 et seq.], the Religious Freedom Restoration Act of 1993 [42 U.S.C. 2000bb et seq.], the Religious Land Use and Institutionalized Persons Act of 2000 [42 U.S.C. 2000cc et seq.], title VI of the Civil Rights Act of 1964 [42 U.S.C. 2000d et seq.], or section 12361 of title 34, the court, in its discretion, may allow the prevailing party, other than the United States, a reasonable attorney's fee as part of the costs, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity such officer shall not be held liable for any costs, including attorney's fees, unless such action was clearly in excess of such officer's jurisdiction."],[0,"(c) Expert fees"],[0,"In awarding an attorney's fee under subsection (b) in any action or proceeding to enforce a provision of section 1981 or 1981a of this title, the court, in its discretion, may include expert fees as part of the attorney's fee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1988?type=usc&year=mostrecent&link-type=html"},"head":"§1988. Proceedings in vindication of civil rights","tname":"The Public Health and Welfare","by":{"0":"8, 31","3":"15"}},{"t":"usc","label":"42 U.S.C. § 2000d","url":"https://www.law.cornell.edu/uscode/text/42/2000d","stext":{"head":"§2000d. Prohibition against exclusion from participation in, denial of benefits of, and discrimination under federally assisted programs on ground of race, color, or national origin","paras":[[0,"No person in the United States shall, on the ground of race, color, or national origin, be excluded from participation in, be denied the benefits of, or be subjected to discrimination under any program or activity receiving Federal financial assistance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000d?type=usc&year=mostrecent&link-type=html"},"head":"§2000d. Prohibition against exclusion from participation in, denial of benefits of, and discrimination under federally assisted programs on ground of race, color, or national origin","tname":"The Public Health and Welfare","by":{"0":"20, 35, 36, 37","1":"5","2":"17"}},{"t":"usc","label":"42 U.S.C. § 2000d-3","url":"https://www.law.cornell.edu/uscode/text/42/2000d-3","stext":{"head":"§2000d–3. Construction of provisions not to authorize administrative action with respect to employment practices except where primary objective of Federal financial assistance is to provide employment","paras":[[0,"Nothing contained in this subchapter shall be construed to authorize action under this subchapter by any department or agency with respect to any employment practice of any employer, employment agency, or labor organization except where a primary objective of the Federal financial assistance is to provide employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000d-3?type=usc&year=mostrecent&link-type=html"},"head":"§2000d–3. Construction of provisions not to authorize administrative action with respect to employment practices except where primary objective of Federal financial assistance is to provide employment","tname":"The Public Health and Welfare","by":{"0":"20, 37","1":"45","2":"27","3":"14, 22"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","subs":["(b)(1964)","(b)","(b)(1976)"],"stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"0":"50","1":"6, 48","2":"1, 6, 6, 6, 6"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(a)(1)"],"stext":{"head":"§2000e–2. Unlawful employment practices","paras":[[0,"(a) Employer practices"],[0,"It shall be an unlawful employment practice for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual, or otherwise to discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(2) to limit, segregate, or classify his employees or applicants for employment in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's race, color, religion, sex, or national origin."],[0,"(b) Employment agency practices"],[0,"It shall be an unlawful employment practice for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin, or to classify or refer for employment any individual on the basis of his race, color, religion, sex, or national origin."],[0,"(c) Labor organization practices"],[0,"It shall be an unlawful employment practice for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin;"],[1,"(2) to limit, segregate, or classify its membership or applicants for membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Training programs"],[0,"It shall be an unlawful employment practice for any employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs to discriminate against any individual because of his race, color, religion, sex, or national origin in admission to, or employment in, any program established to provide apprenticeship or other training."],[0,"(e) Businesses or enterprises with personnel qualified on basis of religion, sex, or national origin; educational institutions with personnel of particular religion"],[0,"Notwithstanding any other provision of this subchapter, (1) it shall not be an unlawful employment practice for an employer to hire and employ employees, for an employment agency to classify, or refer for employment any individual, for a labor organization to classify its membership or to classify or refer for employment any individual, or for an employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining programs to admit or employ any individual in any such program, on the basis of his religion, sex, or national origin in those certain instances where religion, sex, or national origin is a bona fide occupational qualification reasonably necessary to the normal operation of that particular business or enterprise, and (2) it shall not be an unlawful employment practice for a school, college, university, or other educational institution or institution of learning to hire and employ employees of a particular religion if such school, college, university, or other educational institution or institution of learning is, in whole or in substantial part, owned, supported, controlled, or managed by a particular religion or by a particular religious corporation, association, or society, or if the curriculum of such school, college, university, or other educational institution or institution of learning is directed toward the propagation of a particular religion."],[0,"(f) Members of Communist Party or Communist-action or Communist-front organizations"],[0,"As used in this subchapter, the phrase \"unlawful employment practice\" shall not be deemed to include any action or measure taken by an employer, labor organization, joint labor-management committee, or employment agency with respect to an individual who is a member of the Communist Party of the United States or of any other organization required to register as a Communist-action or Communist-front organization by final order of the Subversive Activities Control Board pursuant to the Subversive Activities Control Act of 1950 [50 U.S.C. 781 et seq.]."],[0,"(g) National security"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to fail or refuse to hire and employ any individual for any position, for an employer to discharge any individual from any position, or for an employment agency to fail or refuse to refer any individual for employment in any position, or for a labor organization to fail or refuse to refer any individual for employment in any position, if—"],[1,"(1) the occupancy of such position, or access to the premises in or upon which any part of the duties of such position is performed or is to be performed, is subject to any requirement imposed in the interest of the national security of the United States under any security program in effect pursuant to or administered under any statute of the United States or any Executive order of the President; and"],[1,"(2) such individual has not fulfilled or has ceased to fulfill that requirement."],[0,"(h) Seniority or merit system; quantity or quality of production; ability tests; compensation based on sex and authorized by minimum wage provisions"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to apply different standards of compensation, or different terms, conditions, or privileges of employment pursuant to a bona fide seniority or merit system, or a system which measures earnings by quantity or quality of production or to employees who work in different locations, provided that such differences are not the result of an intention to discriminate because of race, color, religion, sex, or national origin, nor shall it be an unlawful employment practice for an employer to give and to act upon the results of any professionally developed ability test provided that such test, its administration or action upon the results is not designed, intended or used to discriminate because of race, color, religion, sex or national origin. It shall not be an unlawful employment practice under this subchapter for any employer to differentiate upon the basis of sex in determining the amount of the wages or compensation paid or to be paid to employees of such employer if such differentiation is authorized by the provisions of section 206(d) of title 29."],[0,"(i) Businesses or enterprises extending preferential treatment to Indians"],[0,"Nothing contained in this subchapter shall apply to any business or enterprise on or near an Indian reservation with respect to any publicly announced employment practice of such business or enterprise under which a preferential treatment is given to any individual because he is an Indian living on or near a reservation."],[0,"(j) Preferential treatment not to be granted on account of existing number or percentage imbalance"],[0,"Nothing contained in this subchapter shall be interpreted to require any employer, employment agency, labor organization, or joint labor-management committee subject to this subchapter to grant preferential treatment to any individual or to any group because of the race, color, religion, sex, or national origin of such individual or group on account of an imbalance which may exist with respect to the total number or percentage of persons of any race, color, religion, sex, or national origin employed by any employer, referred or classified for employment by any employment agency or labor organization, admitted to membership or classified by any labor organization, or admitted to, or employed in, any apprenticeship or other training program, in comparison with the total number or percentage of persons of such race, color, religion, sex, or national origin in any community, State, section, or other area, or in the available work force in any community, State, section, or other area."],[0,"(k) Burden of proof in disparate impact cases"],[0,"(1)(A) An unlawful employment practice based on disparate impact is established under this subchapter only if—"],[1,"(i) a complaining party demonstrates that a respondent uses a particular employment practice that causes a disparate impact on the basis of race, color, religion, sex, or national origin and the respondent fails to demonstrate that the challenged practice is job related for the position in question and consistent with business necessity; or"],[1,"(ii) the complaining party makes the demonstration described in subparagraph (C) with respect to an alternative employment practice and the respondent refuses to adopt such alternative employment practice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-2?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–2. Unlawful employment practices","tname":"The Public Health and Welfare","by":{"0":"47","1":"6, 48","2":"4, 28"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(b)","(e)(1)"],"stext":{"head":"§2000e–5. Enforcement provisions","paras":[[0,"(a) Power of Commission to prevent unlawful employment practices"],[0,"The Commission is empowered, as hereinafter provided, to prevent any person from engaging in any unlawful employment practice as set forth in section 2000e–2 or 2000e–3 of this title."],[0,"(b) Charges by persons aggrieved or member of Commission of unlawful employment practices by employers, etc.; filing; allegations; notice to respondent; contents of notice; investigation by Commission; contents of charges; prohibition on disclosure of charges; determination of reasonable cause; conference, conciliation, and persuasion for elimination of unlawful practices; prohibition on disclosure of informal endeavors to end unlawful practices; use of evidence in subsequent proceedings; penalties for disclosure of information; time for determination of reasonable cause"],[0,"Whenever a charge is filed by or on behalf of a person claiming to be aggrieved, or by a member of the Commission, alleging that an employer, employment agency, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs, has engaged in an unlawful employment practice, the Commission shall serve a notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) on such employer, employment agency, labor organization, or joint labor-management committee (hereinafter referred to as the \"respondent\") within ten days, and shall make an investigation thereof. Charges shall be in writing under oath or affirmation and shall contain such information and be in such form as the Commission requires. Charges shall not be made public by the Commission. If the Commission determines after such investigation that there is not reasonable cause to believe that the charge is true, it shall dismiss the charge and promptly notify the person claiming to be aggrieved and the respondent of its action. In determining whether reasonable cause exists, the Commission shall accord substantial weight to final findings and orders made by State or local authorities in proceedings commenced under State or local law pursuant to the requirements of subsections (c) and (d). If the Commission determines after such investigation that there is reasonable cause to believe that the charge is true, the Commission shall endeavor to eliminate any such alleged unlawful employment practice by informal methods of conference, conciliation, and persuasion. Nothing said or done during and as a part of such informal endeavors may be made public by the Commission, its officers or employees, or used as evidence in a subsequent proceeding without the written consent of the persons concerned. Any person who makes public information in violation of this subsection shall be fined not more than $1,000 or imprisoned for not more than one year, or both. The Commission shall make its determination on reasonable cause as promptly as possible and, so far as practicable, not later than one hundred and twenty days from the filing of the charge or, where applicable under subsection (c) or (d), from the date upon which the Commission is authorized to take action with respect to the charge."],[0,"(c) State or local enforcement proceedings; notification of State or local authority; time for filing charges with Commission; commencement of proceedings"],[0,"In the case of an alleged unlawful employment practice occurring in a State, or political subdivision of a State, which has a State or local law prohibiting the unlawful employment practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, no charge may be filed under subsection (a) 1 by the person aggrieved before the expiration of sixty days after proceedings have been commenced under the State or local law, unless such proceedings have been earlier terminated, provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective date of such State or local law. If any requirement for the commencement of such proceedings is imposed by a State or local authority other than a requirement of the filing of a written and signed statement of the facts upon which the proceeding is based, the proceeding shall be deemed to have been commenced for the purposes of this subsection at the time such statement is sent by registered mail to the appropriate State or local authority."],[0,"(d) State or local enforcement proceedings; notification of State or local authority; time for action on charges by Commission"],[0,"In the case of any charge filed by a member of the Commission alleging an unlawful employment practice occurring in a State or political subdivision of a State which has a State or local law prohibiting the practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, the Commission shall, before taking any action with respect to such charge, notify the appropriate State or local officials and, upon request, afford them a reasonable time, but not less than sixty days (provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective day of such State or local law), unless a shorter period is requested, to act under such State or local law to remedy the practice alleged."],[0,"(e) Time for filing charges; time for service of notice of charge on respondent; filing of charge by Commission with State or local agency; seniority system"],[0,"(1) A charge under this section shall be filed within one hundred and eighty days after the alleged unlawful employment practice occurred and notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) shall be served upon the person against whom such charge is made within ten days thereafter, except that in a case of an unlawful employment practice with respect to which the person aggrieved has initially instituted proceedings with a State or local agency with authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, such charge shall be filed by or on behalf of the person aggrieved within three hundred days after the alleged unlawful employment practice occurred, or within thirty days after receiving notice that the State or local agency has terminated the proceedings under the State or local law, whichever is earlier, and a copy of such charge shall be filed by the Commission with the State or local agency."],[0,"(2) For purposes of this section, an unlawful employment practice occurs, with respect to a seniority system that has been adopted for an intentionally discriminatory purpose in violation of this subchapter (whether or not that discriminatory purpose is apparent on the face of the seniority provision), when the seniority system is adopted, when an individual becomes subject to the seniority system, or when a person aggrieved is injured by the application of the seniority system or provision of the system."],[0,"(3)(A) For purposes of this section, an unlawful employment practice occurs, with respect to discrimination in compensation in violation of this subchapter, when a discriminatory compensation decision or other practice is adopted, when an individual becomes subject to a discriminatory compensation decision or other practice, or when an individual is affected by application of a discriminatory compensation decision or other practice, including each time wages, benefits, or other compensation is paid, resulting in whole or in part from such a decision or other practice."],[0,"(B) In addition to any relief authorized by section 1981a of this title, liability may accrue and an aggrieved person may obtain relief as provided in subsection (g)(1), including recovery of back pay for up to two years preceding the filing of the charge, where the unlawful employment practices that have occurred during the charge filing period are similar or related to unlawful employment practices with regard to discrimination in compensation that occurred outside the time for filing a charge."],[0,"(f) Civil action by Commission, Attorney General, or person aggrieved; preconditions; procedure; appointment of attorney; payment of fees, costs, or security; intervention; stay of Federal proceedings; action for appropriate temporary or preliminary relief pending final disposition of charge; jurisdiction and venue of United States courts; designation of judge to hear and determine case; assignment of case for hearing; expedition of case; appointment of master"],[0,"(1) If within thirty days after a charge is filed with the Commission or within thirty days after expiration of any period of reference under subsection (c) or (d), the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission may bring a civil action against any respondent not a government, governmental agency, or political subdivision named in the charge. In the case of a respondent which is a government, governmental agency, or political subdivision, if the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission shall take no further action and shall refer the case to the Attorney General who may bring a civil action against such respondent in the appropriate United States district court. The person or persons aggrieved shall have the right to intervene in a civil action brought by the Commission or the Attorney General in a case involving a government, governmental agency, or political subdivision. If a charge filed with the Commission pursuant to subsection (b), is dismissed by the Commission, or if within one hundred and eighty days from the filing of such charge or the expiration of any period of reference under subsection (c) or (d), whichever is later, the Commission has not filed a civil action under this section or the Attorney General has not filed a civil action in a case involving a government, governmental agency, or political subdivision, or the Commission has not entered into a conciliation agreement to which the person aggrieved is a party, the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, shall so notify the person aggrieved and within ninety days after the giving of such notice a civil action may be brought against the respondent named in the charge (A) by the person claiming to be aggrieved or (B) if such charge was filed by a member of the Commission, by any person whom the charge alleges was aggrieved by the alleged unlawful employment practice. Upon application by the complainant and in such circumstances as the court may deem just, the court may appoint an attorney for such complainant and may authorize the commencement of the action without the payment of fees, costs, or security. Upon timely application, the court may, in its discretion, permit the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, to intervene in such civil action upon certification that the case is of general public importance. Upon request, the court may, in its discretion, stay further proceedings for not more than sixty days pending the termination of State or local proceedings described in subsection (c) or (d) of this section or further efforts of the Commission to obtain voluntary compliance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-5?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–5. Enforcement provisions","tname":"The Public Health and Welfare","by":{"0":"48","1":"6, 6, 6, 6, 7","2":"5, 5, 5"}},{"t":"law","label":"Pub. L. No. 88-352","url":"https://www.govinfo.gov/link/statute/78/241","by":{"0":"38","1":"7, 23","2":"6"}},{"t":"law","label":"Pub. L. No. 92-318","url":"https://www.govinfo.gov/link/statute/86/235","by":{"0":"7","1":"8"}},{"t":"law","label":"Pub. L. No. 92-261","url":"https://www.govinfo.gov/link/statute/86/103","by":{"0":"50","1":"7"}},{"t":"law","label":"Pub. L. No. 100-259","url":"https://www.govinfo.gov/link/statute/102/28","by":{"0":"10","2":"29"}},{"t":"usc","label":"42 U.S.C. § 2000d-7","url":"https://www.law.cornell.edu/uscode/text/42/2000d-7","subs":["(a)(1)","(a)(2)"],"stext":{"head":"§2000d–7. Civil rights remedies equalization","paras":[[0,"(a) General provision"],[0,"(1) A State shall not be immune under the Eleventh Amendment of the Constitution of the United States from suit in Federal court for a violation of section 504 of the Rehabilitation Act of 1973 [29 U.S.C. 794], title IX of the Education Amendments of 1972 [20 U.S.C. 1681 et seq.], the Age Discrimination Act of 1975 [42 U.S.C. 6101 et seq.], title VI of the Civil Rights Act of 1964 [42 U.S.C. 2000d et seq.], or the provisions of any other Federal statute prohibiting discrimination by recipients of Federal financial assistance."],[0,"(2) In a suit against a State for a violation of a statute referred to in paragraph (1), remedies (including remedies both at law and in equity) are available for such a violation to the same extent as such remedies are available for such a violation in the suit against any public or private entity other than a State."],[0,"(b) Effective date"],[0,"The provisions of subsection (a) shall take effect with respect to violations that occur in whole or in part after October 21, 1986."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000d-7?type=usc&year=mostrecent&link-type=html"},"head":"§2000d–7. Civil rights remedies equalization","tname":"The Public Health and Welfare","by":{"0":"9, 19, 24, 43, 44, 52, 53","1":"42, 38","2":"25, 7, 7","3":"11, 17"}},{"t":"const","label":"Article I, Section 8, Clause 1","clauses":[["taxing-spending","Taxing and Spending Clause"]],"text":"The Congress shall have Power To lay and collect Taxes, Duties, Imposts and Excises, to pay the Debts and provide for the common Defence and general Welfare of the United States; but all Duties, Imposts and Excises shall be uniform throughout the United States;","by":{"0":"2"}},{"t":"reg","label":"28 C.F.R. § 54.510-54","url":"https://www.ecfr.gov/current/title-28/section-54.510-54","by":{"0":"33"}},{"t":"reg","label":"34 C.F.R. § 106.51-106","url":"https://www.ecfr.gov/current/title-34/section-106.51-106","by":{"0":"33, 56"}},{"t":"reg","label":"45 C.F.R. § 86.51-86","url":"https://www.ecfr.gov/current/title-45/section-86.51-86","by":{"0":"33"}},{"t":"reg","label":"7 C.F.R. pt. 15","url":"https://www.ecfr.gov/current/title-7/part-15","by":{"0":"33"}},{"t":"case","label":"U.S. Br., North Haven Bd. of Educ. v. Bell","cite":"1981 WL 390417","y":1981,"court":"Sept. 3","by":{"0":"12"}},{"t":"case","label":"U.S. Br., Cannon v. Univ. of Chicago","cite":"1978 WL 207068","y":1978,"court":"Mar. 3","by":{"0":"12"}},{"t":"case","label":"U.S. Br., Cannon v. Univ. of Chicago","cite":"1978 WL 223506","y":1978,"court":"Nov. 2","by":{"0":"12"}},{"t":"case","label":"U.S. Br., Doe v. Mercy","cite":"2016 WL 3227568","y":2016,"court":"June 9","by":{"0":"12"}},{"t":"case","label":"U.S. Br., Jackson v. Birmingham Bd. of Educ.","cite":"2004 WL 1062111","y":2004,"court":"May 11","by":{"0":"12"}},{"t":"case","label":"U.S. Br., Jackson v. Birmingham Bd. of Educ.","cite":"2004 WL 1900496","y":2004,"court":"Aug. 19","by":{"0":"12"}},{"t":"case","label":"U.S. Br., Lakoski v. Univ. of Tx. Med. Branch at Galveston","cite":"1996 WL 33467394","y":1996,"court":"Sept. 24","by":{"0":"12"}},{"t":"case","label":"AMG Cap. Mgmt., LLC v. FTC","cite":"593 U.S. 67","y":2021,"url":"https://supreme.justia.com/cases/federal/us/593/67/","sc":1,"by":{"1":"39"}},{"t":"case","label":"Armour & Co. v. Wantock","cite":"323 U.S. 126","y":1944,"id":"scdb/1944-014","sc":1,"sum":"1. Fireguards employed by a manufacturer of goods for interstate comnerce, held covered by the Fair Labor Standards Act of 1938, as employed in an \"occupation necessary to the production\" of goods for interstate commerce.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Astra USA, Inc. v. Santa Clara Cnty.","cite":"563 U.S. 110","y":2011,"id":"2010/09-1273","sc":1,"sum":"The Court held that health care providers cannot sue drug makers for overcharging public hospitals for prescription drugs.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"BP P.L.C. v. Mayor & City Council of Baltimore","cite":"593 U.S. 230","y":2021,"id":"2020/19-1189","sc":1,"sum":"Where defendant energy companies premised 28 U. S. C. §1447(d) removal in part on the federal officer removal statute, §1442, the Fourth Circuit erred in holding that it lacked jurisdiction to consider all grounds for removal rejected by the District Court.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"40","2":"28"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of the Federal Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"1":"22, 42, 43"}},{"t":"case","label":"Blue Chip Stamps v. Manor Drug Stores","cite":"421 U.S. 723","y":1975,"id":"1974/74-124","sc":1,"sum":"A private damages action under Rule 10b-5 is confined to actual purchasers or sellers of securities and the Birnbaum rule bars respondent from maintaining this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 19","2":"19"}},{"t":"case","label":"Cited Authorities Page Bostock v. Clayton Cnty.","cite":"590 U.S. 644","y":2020,"url":"https://supreme.justia.com/cases/federal/us/590/644/","sc":1,"by":{"1":"2, 5"}},{"t":"case","label":"Brecht v. Abrahamson","cite":"507 U.S. 619","y":1993,"id":"1992/91-7358","sc":1,"sum":"Chief Justice William H. Rehnquist wrote that the \"substantial and injurious effect\" test was preferable to the \"beyond a reasonable doubt\" test in requests for habeas corpus relief. Habeas proceedings are not to be the primary avenue for resolving disputes; Rehnquist called the writ \"an extraordinary remedy\", reserved for the victims of grave injustice.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Brown v. Davenport","cite":"596 U.S. 118","y":2022,"id":"2021/20-826","sc":1,"sum":"When a state court has ruled on the merits of a state prisoner’s claim, a federal court cannot grant habeas relief without applying both the test this Court outlined in Brecht v. Abrahamson, 507 U. S. 619, and the one Congress prescribed in the Antiterrorism and Effective Death Penalty Act of 1996; the Sixth Circuit erred in granting habeas relief to Mr. Davenport based solely on its assessment that he could satisfy the Brecht standard.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"31, 33"}},{"t":"case","label":"Brown v. GSA","cite":"425 U.S. 820","y":1976,"id":"1975/74-768","sc":1,"sum":"Section 717 provides the exBROWN v. GSA","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13, 24, 25, 27","2":"3, 10, 20, 24","3":"24, 25"}},{"t":"case","label":"Carlson v. Green","cite":"446 U.S. 14","y":1980,"id":"1979/78-1261","sc":1,"sum":"Respondent brought suit in Federal District Court in Indiana on behalf of her deceased son's estate, alleging that her son while a prisoner in a federal prison in Indiana suffered personal injuries from which he died because petitioner prison officials violated, inter alia, his Eighth Amendment rights by failing to give him proper medical attention. Asserting jurisdiction under 28 U. S. C. § 1331 (a), respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Cent. Va. Cmty. Coll. v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"sum":"The Court ruled that states cannot invoke sovereign immunity as a defense in bankruptcy proceedings. Rather than ruling on the power of Congress under the Bankruptcy Clause to waive states' immunity, as the bankruptcy court did, the Court held that ratification of the Clause itself involved a subordination of state sovereign immunity.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Cohens v. Virginia","cite":"6 Wheat. 264","y":1821,"url":"https://www.courtlistener.com/c/Wheat./6/264/","by":{"1":"30, 32"}},{"t":"case","label":"Cuddeback v. Fla. Bd. of Educ.","cite":"381 F.3d 1230","y":2004,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/381/1230/","by":{"1":"49"}},{"t":"case","label":"Del. State Coll. v. Ricks","cite":"449 U.S. 250","y":1980,"id":"1980/79-939","sc":1,"sum":"Respondent's Title VII and § 1981 claims were untimely.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28","2":"6"}},{"t":"case","label":"Egbert v. Boule","cite":"596 U.S. 482","y":2022,"id":"2021/21-147","sc":1,"sum":"The authority of a court to imply a cause of action under Bivens v. Six Unknown Fed. Narcotics Agents, 403 U. S. 388, does not extend to either Boule’s Fourth Amendment excessive-force claim or his First Amendment retaliation claim.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"15, 18, 22, 43"}},{"t":"case","label":"Fitzpatrick v. Bitzer","cite":"427 U.S. 445","y":1976,"id":"1975/75-251","sc":1,"sum":"Present and retired male employees of the State of Connecticut (petitioners in No. 75-251) brought this class action alleging, inter alia, that certain provisions of the State's statutory retirement benefit plan discriminated against them because of their sex, in violation of Title VII of the Civil Rights Act of 1964, which, as amended, extends coverage to the States as employers. The District Court ruled in their …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"6, 41"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"588 U.S. 427","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"39, 40"}},{"t":"case","label":"Gonzaga Univ. v. Doe","cite":"536 U.S. 273","y":2002,"id":"2001/01-679","sc":1,"sum":"The Court held that such an action is foreclosed because the relevant provisions of FERPA create no personal rights to enforce.","sumSrc":"Oyez","by":{"1":"15, 20","2":"10, 14, 15, 18, 19"}},{"t":"case","label":"Great Am. Fed. Sav. & Loan Ass’n v. Novotny","cite":"442 U.S. 366","y":1979,"id":"1978/78-753","sc":1,"sum":"Section 1985 (3) may not be invoked to redress violations of Title VII. It creates no substantive rights itself but is a purely remedial statute, providing a civil cause of action when some otherwise defined federal right-to equal protection of the laws or equal privileges and immunities under the laws-is breached by a conspiracy in the manner defined by the section. Thus, the question in this case is whether rights …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3, 6, 23, 25","2":"3, 5, 20, 24, 25","3":"24, 25, 26"}},{"t":"case","label":"Hackley v. Roudebush","cite":"520 F.2d 108","y":1975,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/520/108/","by":{"1":"7"}},{"t":"case","label":"Hamilton v. Dallas Cnty.","cite":"79 F.4th 494","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/79/494/","by":{"1":"49"}},{"t":"case","label":"Hernandez v. Mesa","cite":"589 U.S. 93","y":2020,"id":"2019/17-1678","sc":1,"sum":"The Court held that the family of a Mexican teenager who was killed by a U.S. Border Patrol agent in a cross-border shooting cannot sue the agent for damages under the U.S. Constitution.","sumSrc":"Oyez","by":{"1":"42","2":"26"}},{"t":"case","label":"Hishon v. King & Spalding","cite":"467 U.S. 69","y":1984,"id":"1983/82-940","sc":1,"sum":"The Court held that Title VII makes it illegal for an employer to discriminate against any employee on the basis of their sex. In this case, the Court held that the promise of equal consideration for partnership that went along with Hishon’s employment was contractual in nature and subject to the regulations of Title VII.","sumSrc":"Oyez","by":{"1":"48, 49"}},{"t":"case","label":"Cited Authorities Page Jackson v. Birmingham Bd. of Educ.","cite":"309 F.3d 1333","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/309/1333/","by":{"1":"34"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"1":"4, 14, 39-41"}},{"t":"case","label":"Janus Cap. Grp. v. First Derivative Traders","cite":"564 U.S. 135","y":2011,"id":"2010/09-525","sc":1,"sum":"The Court held that a service provider cannot be held liable for statements for which they are not directly responsible.","sumSrc":"Oyez","by":{"1":"19","2":"14"}},{"t":"case","label":"Karahalios v. Nat’l Fed’n of Fed. Emps., Loc. 1263","cite":"489 U.S. 527","y":1989,"id":"1988/87-636","sc":1,"sum":"Title VII of the CSRA does not confer on federal employees a private cause of action against a breach by a union representing such employees of its statutory duty of fair representation.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Kimble v. Marvel Ent., LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Kimel v. Fla. Bd. of Regents","cite":"528 U.S. 62","y":2000,"id":"1999/98-791","sc":1,"sum":"The Court held that the ADEA contains a clear statement of Congress' intent to abrogate the states' immunity, but that the abrogation exceeds Congress' authority under the Fourteenth Amendment. \"States may discriminate on the basis of age without offending the Fourteenth Amendment if the age classification in question is rationally related to a legitimate state interest,\" wrote Justice O'Connor for the Court.","sumSrc":"Oyez","by":{"1":"39, 41"}},{"t":"case","label":"Lakoski v. James","cite":"66 F.3d 751","y":1995,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/66/751/","by":{"1":"23"}},{"t":"case","label":"Cited Authorities Page Lexmark Int’l, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Lowrey v. Tex. A&M Univ. Sys.","cite":"117 F.3d 242","y":1997,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/117/242/","by":{"1":"34"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"575 U.S. 480","y":2015,"id":"2014/13-1019","sc":1,"sum":"The Court held that judicial review of the Equal Employment Opportunity Commission’s efforts at conciliation is appropriate, but such review must be limited to the narrow requirements that Title VII imposes.","sumSrc":"Oyez","by":{"1":"6, 28","2":"5, 30"}},{"t":"case","label":"Mass. Mut. Life Ins. Co. v. Russell","cite":"473 U.S. 134","y":1985,"id":"1984/84-9","sc":1,"sum":"Section 409(a) does not provide a cause of action for extracontractual damages to a beneficiary caused by improper or untimely processing of benefit claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16, 17","2":"15"}},{"t":"case","label":"Mawakana v. Bd. of Trs. of Univ. of D.C.","cite":"926 F.3d 859","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/926/859/","by":{"1":"23"}},{"t":"case","label":"Medina v. Planned Parenthood S. Atl.","cite":"606 U.S. 357","y":2025,"id":"2024/23-1275","sc":1,"sum":"Medicaid’s any-qualified-provider provision—42 U. S. C. §1396a(a)(23)(A)—does not clearly and unambiguously confer individual rights on Medicaid beneficiaries enforceable under 42 U. S. C. §1983.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"1, 3, 4, 8, 13, 15, 16, 20, 21, 31","2":"4, 13, 14, 18, 21"}},{"t":"case","label":"Middlesex Cnty. Sewerage Auth. v. Nat’l Sea Clammers Ass’n","cite":"453 U.S. 1","y":1981,"id":"1980/79-1711","sc":1,"sum":"Respondents (an organization whose members harvest fish and shellfish off the coast of New York and New Jersey and one individual member) brought suit in Federal District Court against petitioners (various governmental entities and officials from New York, New Jersey, and the Federal Government), alleging damage to fishing grounds caused by discharges and ocean dumping of sewage and other waste. Invoking a number of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18","2":"22","3":"25"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"1":"50"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"1":"24","3":"22"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"1":"35, 36"}},{"t":"case","label":"Nw. Airlines, Inc. v. Transp. Workers Union of Am., AFL-CIO","cite":"451 U.S. 77","y":1981,"id":"1980/79-1056","sc":1,"sum":"Petitioner has neither a federal statutory nor a federal common-law right to contribution from respondent unions.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"1, 2, 16, 17, 23"}},{"t":"case","label":"Oklahoma v. Castro-Huerta","cite":"597 U.S. 629","y":2022,"id":"2021/21-429","sc":1,"sum":"The Federal Government and the State have concurrent jurisdiction to prosecute crimes committed by non-Indians against Indians in Indian country.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"38, 39"}},{"t":"case","label":"Pasquantino v. United States","cite":"544 U.S. 349","y":2005,"id":"2004/03-725","sc":1,"sum":"The Court held that the law's plain language criminalized the smuggling scheme in this case. The common-law revenue rule did not bar the prosecution of the scheme, because no common-law case as of 1952 clearly established that the rule barred the U.S. from prosecuting a fraudulent scheme to evade foreign taxes.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"584 U.S. 357","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"1":"5, 47"}},{"t":"case","label":"Seminole Tribe of Fla. v. Fla.","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"1":"30, 31"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"1":"22, 43"}},{"t":"case","label":"Cited Authorities Page Stoneridge Inv. Partners, LLC v. Sci.-Atlanta","cite":"552 U.S. 148","y":2008,"id":"2007/06-43","sc":1,"sum":"The Court held that, under Central Bank and Section 10(b), securities fraud plaintiffs cannot sue \"aiders and abettors\" like Scientific-Atlanta. The Court noted Congress' subsequent failure to create a right of private action against aiders and abettors in the Private Securities Litigation Reform Act for support of its position that no such right should be allowed in the present case.","sumSrc":"Oyez","by":{"1":"19","2":"26","3":"11"}},{"t":"case","label":"Summy-Long v. Pa. State Univ.","cite":"715 F. App’x 179","y":2017,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/715/179/","by":{"1":"50"}},{"t":"case","label":"Touche Ross & Co. v. Redington","cite":"442 U.S. 560","y":1979,"id":"1978/78-309","sc":1,"sum":"There is no implied private cause of action for damages under § 17 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18","2":"14"}},{"t":"case","label":"Town of Chester, N.Y. v. Laroe Ests., Inc.","cite":"581 U.S. 433","y":2017,"id":"2016/16-605","sc":1,"sum":"The Court determined that an intervenor to a lawsuit must meet the requirements of Article III standing if the intervenor wishes to pursue relief that was not already requested by the plaintiff.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"594 U.S. 413","y":2021,"id":"2020/20-297","sc":1,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20"}},{"t":"case","label":"Transamerica Mortg. Advisors Inc. (TAMA) v. Lewis","cite":"444 U.S. 11","y":1979,"id":"1978/77-1645","sc":1,"sum":"Respondent, a shareholder of petitioner Mortgage Trust of America (Trust), brought this suit in Federal District Court as a derivative action on behalf of the Trust and as a class action on behalf of the Trust's shareholders, alleging that several trustees of the Trust, its investment adviser, and two corporations affiliated with the latter, had been guilty of various frauds and breaches of fiduciary duty in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3, 16, 17, 23, 48"}},{"t":"case","label":"United States v. Rahimi","cite":"602 U.S. 680","y":2024,"id":"2023/22-915","sc":1,"sum":"When an individual has been found by a court to pose a credible threat to the physical safety of another, that individual may be temporarily disarmed consistent with the Second Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"29"}},{"t":"case","label":"Univ. of Pa. v. EEOC","cite":"493 U.S. 182","y":1990,"id":"1989/88-493","sc":1,"sum":"A unanimous Court held that the need to ferret out invidious discrimination served a compelling government interest which justified inspection of confidential files.","sumSrc":"Oyez","by":{"1":"6","2":"5"}},{"t":"case","label":"Vengalattore v. Cornell Univ.","cite":"36 F.4th 87","y":2022,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/36/87/","by":{"1":"50"}},{"t":"case","label":"Virginia Bankshares, Inc. v. Sandberg","cite":"501 U.S. 1083","y":1991,"id":"1990/89-1448","sc":1,"sum":"Respectively. Terms like \"high value,\" in a commercial context, are reasonably understood to rest on a factual basis, and so could be shown to be misleading by garden-variety evidence. Furthermore, they can be materially misleading even if other information is available in the statement upon which an expert could deduce that they are false. A proxy statement should inform, not challenge the reader's critical wits.","sumSrc":"Oyez","by":{"1":"3, 16, 19, 26","2":"15, 17"}},{"t":"case","label":"xiii Cited Authorities Page Webster v. Fall","cite":"266 U.S. 507","y":1925,"id":"scdb/1924-066","sc":1,"sum":"1. A suit lacking a necessary party defendant should be dismissed' on that ground without deciding the merits.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Weise v. Syracuse Univ.","cite":"522 F.2d 397","y":1975,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/522/397/","by":{"1":"7"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"id":"2016/15-1358","sc":1,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"1":"43","2":"15"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"1":"42"}},{"t":"const","label":"Amendment XI","clauses":[["eleventh-amendment","Eleventh Amendment"]],"text":"The Judicial power of the United States shall not be construed to extend to any suit in law or equity, commenced or prosecuted against one of the United States by Citizens of another State, or by Citizens or Subjects of any Foreign State.","by":{"1":"38, 41"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"1":"6"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"1":"49"}},{"t":"usc","label":"29 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/29/206","subs":["(d)"],"stext":{"head":"§206. Minimum wage","paras":[[0,"(a) Employees engaged in commerce; home workers in Puerto Rico and Virgin Islands; employees in American Samoa; seamen on American vessels; agricultural employees"],[0,"Every employer shall pay to each of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, wages at the following rates:"],[1,"(1) except as otherwise provided in this section, not less than—"],[2,"(A) $5.85 an hour, beginning on the 60th day after May 25, 2007;"],[2,"(B) $6.55 an hour, beginning 12 months after that 60th day; and"],[2,"(C) $7.25 an hour, beginning 24 months after that 60th day;"],[1,"(2) if such employee is a home worker in Puerto Rico or the Virgin Islands, not less than the minimum piece rate prescribed by regulation or order; or, if no such minimum piece rate is in effect, any piece rate adopted by such employer which shall yield, to the proportion or class of employees prescribed by regulation or order, not less than the applicable minimum hourly wage rate. Such minimum piece rates or employer piece rates shall be commensurate with, and shall be paid in lieu of, the minimum hourly wage rate applicable under the provisions of this section. The Administrator, or his authorized representative, shall have power to make such regulations or orders as are necessary or appropriate to carry out any of the provisions of this paragraph, including the power without limiting the generality of the foregoing, to define any operation or occupation which is performed by such home work employees in Puerto Rico or the Virgin Islands; to establish minimum piece rates for any operation or occupation so defined; to prescribe the method and procedure for ascertaining and promulgating minimum piece rates; to prescribe standards for employer piece rates, including the proportion or class of employees who shall receive not less than the minimum hourly wage rate; to define the term \"home worker\"; and to prescribe the conditions under which employers, agents, contractors, and subcontractors shall cause goods to be produced by home workers;"],[1,"(3) if such employee is employed as a seaman on an American vessel, not less than the rate which will provide to the employee, for the period covered by the wage payment, wages equal to compensation at the hourly rate prescribed by paragraph (1) of this subsection for all hours during such period when he was actually on duty (including periods aboard ship when the employee was on watch or was, at the direction of a superior officer, performing work or standing by, but not including off-duty periods which are provided pursuant to the employment agreement); or"],[1,"(4) if such employee is employed in agriculture, not less than the minimum wage rate in effect under paragraph (1) after December 31, 1977."],[0,"(b) Additional applicability to employees pursuant to subsequent amendatory provisions"],[0,"Every employer shall pay to each of his employees (other than an employee to whom subsection (a)(5) 1 applies) who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, and who in such workweek is brought within the purview of this section by the amendments made to this chapter by the Fair Labor Standards Amendments of 1966, title IX of the Education Amendments of 1972 [20 U.S.C. 1681 et seq.], or the Fair Labor Standards Amendments of 1974, wages at the following rate: Effective after December 31, 1977, not less than the minimum wage rate in effect under subsection (a)(1)."],[0,"(c) Repealed. Pub. L. 104–188, [title II], §2104(c), Aug. 20, 1996, 110 Stat. 1929"],[0,"(d) Prohibition of sex discrimination"],[0,"(1) No employer having employees subject to any provisions of this section shall discriminate, within any establishment in which such employees are employed, between employees on the basis of sex by paying wages to employees in such establishment at a rate less than the rate at which he pays wages to employees of the opposite sex in such establishment for equal work on jobs the performance of which requires equal skill, effort, and responsibility, and which are performed under similar working conditions, except where such payment is made pursuant to (i) a seniority system; (ii) a merit system; (iii) a system which measures earnings by quantity or quality of production; or (iv) a differential based on any other factor other than sex: Provided, That an employer who is paying a wage rate differential in violation of this subsection shall not, in order to comply with the provisions of this subsection, reduce the wage rate of any employee."],[0,"(2) No labor organization, or its agents, representing employees of an employer having employees subject to any provisions of this section shall cause or attempt to cause such an employer to discriminate against an employee in violation of paragraph (1) of this subsection."],[0,"(3) For purposes of administration and enforcement, any amounts owing to any employee which have been withheld in violation of this subsection shall be deemed to be unpaid minimum wages or unpaid overtime compensation under this chapter."],[0,"(4) As used in this subsection, the term \"labor organization\" means any organization of any kind, or any agency or employee representation committee or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours of employment, or conditions of work."],[0,"(e) Employees of employers providing contract services to United States"],[0,"(1) Notwithstanding the provisions of section 213 of this title (except subsections (a)(1) and (f) thereof), every employer providing any contract services (other than linen supply services) under a contract with the United States or any subcontract thereunder shall pay to each of his employees whose rate of pay is not governed by chapter 67 of title 41 or to whom subsection (a)(1) of this section is not applicable, wages at rates not less than the rates provided for in subsection (b) of this section."],[0,"(2) Notwithstanding the provisions of section 213 of this title (except subsections (a)(1) and (f) thereof) and the provisions of chapter 67 of title 41, every employer in an establishment providing linen supply services to the United States under a contract with the United States or any subcontract thereunder shall pay to each of his employees in such establishment wages at rates not less than those prescribed in subsection (b), except that if more than 50 per centum of the gross annual dollar volume of sales made or business done by such establishment is derived from providing such linen supply services under any such contracts or subcontracts, such employer shall pay to each of his employees in such establishment wages at rates not less than those prescribed in subsection (a)(1) of this section."],[0,"(f) Employees in domestic service"],[0,"Any employee—"],[1,"(1) who in any workweek is employed in domestic service in a household shall be paid wages at a rate not less than the wage rate in effect under subsection (b) unless such employee's compensation for such service would not because of section 209(a)(6) of the Social Security Act [42 U.S.C. 409(a)(6)] constitute wages for the purposes of title II of such Act [42 U.S.C. 401 et seq.], or"],[1,"(2) who in any workweek—"],[2,"(A) is employed in domestic service in one or more households, and"],[2,"(B) is so employed for more than 8 hours in the aggregate,"],[0,"shall be paid wages for such employment in such workweek at a rate not less than the wage rate in effect under subsection (b)."],[0,"(g) Newly hired employees who are less than 20 years old"],[0,"(1) In lieu of the rate prescribed by subsection (a)(1), any employer may pay any employee of such employer, during the first 90 consecutive calendar days after such employee is initially employed by such employer, a wage which is not less than $4.25 an hour."],[0,"(2) In lieu of the rate prescribed by subsection (a)(1), the Governor of Puerto Rico, subject to the approval of the Financial Oversight and Management Board established pursuant to section 2121 of title 48, may designate a time period not to exceed four years during which employers in Puerto Rico may pay employees who are initially employed after June 30, 2016, a wage which is not less than the wage described in paragraph (1). Notwithstanding the time period designated, such wage shall not continue in effect after such Board terminates in accordance with section 2149 of title 48."],[0,"(3) No employer may take any action to displace employees (including partial displacements such as reduction in hours, wages, or employment benefits) for purposes of hiring individuals at the wage authorized in paragraph (1) or (2)."],[0,"(4) Any employer who violates this subsection shall be considered to have violated section 215(a)(3) of this title."],[0,"(5) This subsection shall only apply to an employee who has not attained the age of 20 years, except in the case of the wage applicable in Puerto Rico, 25 years, until such time as the Board described in paragraph (2) terminates in accordance with section 2149 of title 48."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/206?type=usc&year=mostrecent&link-type=html"},"head":"§206. Minimum wage","tname":"Labor","by":{"1":"49","2":"6"}},{"t":"usc","label":"29 U.S.C. § 794a","url":"https://www.law.cornell.edu/uscode/text/29/794a","subs":["(a)(2)"],"by":{"1":"46"}},{"t":"usc","label":"29 U.S.C. § 2601","url":"https://www.law.cornell.edu/uscode/text/29/2601","by":{"1":"49"}},{"t":"usc","label":"42 U.S.C. § 1981","url":"https://www.law.cornell.edu/uscode/text/42/1981","stext":{"head":"§1981. Equal rights under the law","paras":[[0,"(a) Statement of equal rights"],[0,"All persons within the jurisdiction of the United States shall have the same right in every State and Territory to make and enforce contracts, to sue, be parties, give evidence, and to the full and equal benefit of all laws and proceedings for the security of persons and property as is enjoyed by white citizens, and shall be subject to like punishment, pains, penalties, taxes, licenses, and exactions of every kind, and to no other."],[0,"(b) \"Make and enforce contracts\" defined"],[0,"For purposes of this section, the term \"make and enforce contracts\" includes the making, performance, modification, and termination of contracts, and the enjoyment of all benefits, privileges, terms, and conditions of the contractual relationship."],[0,"(c) Protection against impairment"],[0,"The rights protected by this section are protected against impairment by nongovernmental discrimination and impairment under color of State law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1981?type=usc&year=mostrecent&link-type=html"},"head":"§1981. Equal rights under the law","tname":"The Public Health and Welfare","by":{"1":"24, 25","2":"11, 20, 23"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"1":"44","2":"14"}},{"t":"usc","label":"42 U.S.C. § 1985","url":"https://www.law.cornell.edu/uscode/text/42/1985","subs":["(3)"],"stext":{"head":"§1985. Conspiracy to interfere with civil rights","paras":[[0,"(1) Preventing officer from performing duties"],[0,"If two or more persons in any State or Territory conspire to prevent, by force, intimidation, or threat, any person from accepting or holding any office, trust, or place of confidence under the United States, or from discharging any duties thereof; or to induce by like means any officer of the United States to leave any State, district, or place, where his duties as an officer are required to be performed, or to injure him in his person or property on account of his lawful discharge of the duties of his office, or while engaged in the lawful discharge thereof, or to injure his property so as to molest, interrupt, hinder, or impede him in the discharge of his official duties;"],[0,"(2) Obstructing justice; intimidating party, witness, or juror"],[0,"If two or more persons in any State or Territory conspire to deter, by force, intimidation, or threat, any party or witness in any court of the United States from attending such court, or from testifying to any matter pending therein, freely, fully, and truthfully, or to injure such party or witness in his person or property on account of his having so attended or testified, or to influence the verdict, presentment, or indictment of any grand or petit juror in any such court, or to injure such juror in his person or property on account of any verdict, presentment, or indictment lawfully assented to by him, or of his being or having been such juror; or if two or more persons conspire for the purpose of impeding, hindering, obstructing, or defeating, in any manner, the due course of justice in any State or Territory, with intent to deny to any citizen the equal protection of the laws, or to injure him or his property for lawfully enforcing, or attempting to enforce, the right of any person, or class of persons, to the equal protection of the laws;"],[0,"(3) Depriving persons of rights or privileges"],[0,"If two or more persons in any State or Territory conspire or go in disguise on the highway or on the premises of another, for the purpose of depriving, either directly or indirectly, any person or class of persons of the equal protection of the laws, or of equal privileges and immunities under the laws; or for the purpose of preventing or hindering the constituted authorities of any State or Territory from giving or securing to all persons within such State or Territory the equal protection of the laws; or if two or more persons conspire to prevent by force, intimidation, or threat, any citizen who is lawfully entitled to vote, from giving his support or advocacy in a legal manner, toward or in favor of the election of any lawfully qualified person as an elector for President or Vice President, or as a Member of Congress of the United States; or to injure any citizen in person or property on account of such support or advocacy; in any case of conspiracy set forth in this section, if one or more persons engaged therein do, or cause to be done, any act in furtherance of the object of such conspiracy, whereby another is injured in his person or property, or deprived of having and exercising any right or privilege of a citizen of the United States, the party so injured or deprived may have an action for the recovery of damages occasioned by such injury or deprivation, against any one or more of the conspirators."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1985?type=usc&year=mostrecent&link-type=html"},"head":"§1985. Conspiracy to interfere with civil rights","tname":"The Public Health and Welfare","by":{"1":"24, 25","2":"20, 24"}},{"t":"usc","label":"42 U.S.C. § 2000d-1","url":"https://www.law.cornell.edu/uscode/text/42/2000d-1","by":{"1":"5"}},{"t":"usc","label":"42 U.S.C. § 12112","url":"https://www.law.cornell.edu/uscode/text/42/12112","subs":["(a)"],"by":{"1":"46"}},{"t":"usc","label":"42 U.S.C. § 12117","url":"https://www.law.cornell.edu/uscode/text/42/12117","by":{"1":"46"}},{"t":"law","label":"Pub. L. No. 93-112","url":"https://www.govinfo.gov/link/statute/87/355","by":{"1":"45","2":"27"}},{"t":"law","label":"Pub. L. No. 102-569","url":"https://www.govinfo.gov/link/statute/106/4344","by":{"1":"48"}},{"t":"reg","label":"29 C.F.R. pt. 1600","url":"https://www.ecfr.gov/current/title-29/part-1600","by":{"1":"48"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"Chadbourne & Parke LLP v. Troice","cite":"571 U.S. 377","y":2014,"id":"2013/12-79","sc":1,"sum":"The Court held that the Securities Litigation Uniform Standards Act does not extend its scope beyond misrepresentations that are material to the sale of a closed financial security.","sumSrc":"Oyez","by":{"2":"17, 23"}},{"t":"case","label":"Cisco Sys., Inc. v. Doe","cite":"146 S. Ct. 1882","y":2026,"id":"2025/24-856","sc":1,"sum":"The Court held that neither the Alien Tort Statute nor the Torture Victim Protection Act supplies a judicially implied private right of action for aiding-and-abetting liability.","sumSrc":"Oyez","by":{"2":"2, 13, 19, 27, 29","3":"4, 11"}},{"t":"case","label":"Clackamas Gastroenterology Assocs., P.C. v. Wells","cite":"538 U.S. 440","y":2003,"id":"2002/01-1435","sc":1,"sum":"The Court held that the common-law element of control is the principal guidepost to be followed in deciding whether the four director-shareholder physicians in this case should be counted as employees and listed six factors that are relevant to such a decision. \"Because the District Court's findings appear to weigh in favor of concluding that the four physicians are not clinic employees, but evidence in the record may contradict those findings or support a contrary conclusion,\" the Court remanded the case for a determination under the new standard.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Comcast Corp. v. National Ass’n of African Am.-Owned Media","cite":"589 U.S. 327","y":2020,"id":"2019/18-1171","sc":1,"sum":"The Court held that a claim of race discrimination under 42 U.S.C. § 1981 requires that the plaintiff show that race was a but-for cause of the plaintiff's injury.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Cooper Indus., Inc. v. Aviall Servs., Inc.","cite":"543 U.S. 157","y":2004,"id":"2004/02-1192","sc":1,"sum":"The Court held that a private party, who, like Aviall, had not been sued under CERCLA could not obtain cleanup contributions from other liable parties. The Court reasoned that CERCLA's language made clear that parties could seek cleanup contribution only during or following a civil action.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Daily Income Fund, Inc. v. Fox","cite":"464 U.S. 523","y":1984,"id":"1983/82-1200","sc":1,"sum":"Rule 23.1 does not apply to an action brought by an investment company shareholder under § 36(b), and thus the plaintiff in such a case need not first make a demand upon the company's directors before bringing suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"EEOC v. Waffle House, Inc.","cite":"534 U.S. 279","y":2002,"id":"2001/99-1823","sc":1,"sum":"The Court held that the arbitration agreement did not bar the EEOC from pursuing victim-specific judicial relief in an ADA enforcement action. The Court reasoned that the EECO's statutory enforcement powers unambiguously authorized the EEOC to obtain the relief that it sought in its complaint, if it could prove its case against the employer.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"sum":"Petitioner accounting firm was retained to audit periodically a brokerage firm's books and records. Respondents, who were customers of the brokerage firm, invested in a securities scheme ultimately revealed as fraudulent and perpetrated by the firm's president and principal stockholder. After the fraud came to light, respondents filed an action for damages against petitioner under § 10 (b) of the Securities Exchange …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"FS Credit Opportunities Corp. v. Saba Capital Master Fund, Ltd.","cite":"146 S. Ct. 1546","y":2026,"id":"2025/24-345","sc":1,"sum":"Section 47(b) of the Investment Company Act does not impliedly empower private parties to sue for rescission of contracts that allegedly violate the Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"2, 13, 22, 25, 26, 31","3":"3"}},{"t":"case","label":"Fort Bend County v. Davis","cite":"587 U.S. 541","y":2019,"id":"2018/18-525","sc":1,"sum":"The charge-filing precondition to suit set out in Title VII of the Civil Rights Act of 1964 is not a jurisdictional requirement.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"6"}},{"t":"case","label":"Gross v. FBL Fin. Servs., Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"sum":"The Court held that there is no undue burden in allowing defendants in securities fraud cases from presenting evidence regarding the alleged impact of the misinformation on stock prices.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Hinck v. United States","cite":"550 U.S. 501","y":2007,"id":"2006/06-376","sc":1,"sum":"The Court reasoned that its ruling was consistent with the principle that when Congress enacts a detailed, specific judicial remedy (such as 6404(e)(1)) where there was no remedy before, the new remedy will be regarded as exclusive.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Jesner v. Arab Bank, PLC","cite":"584 U.S. 241","y":2018,"id":"2017/16-499","sc":1,"sum":"The Court held that the Alien Tort Statute does not permit lawsuits against corporations.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Landor v. Louisiana Dep’t of Corr. & Pub. Safety","cite":"146 S. Ct. 1931","y":2026,"id":"2025/23-1197","sc":1,"sum":"The Court held that an individual may not sue a government official in his individual capacity for damages for violations of the Religious Land Use and Institutionalized Persons Act (RLUIPA).","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"Lightfoot v. Cendant Mortg. Corp.","cite":"580 U.S. 82","y":2017,"id":"2016/14-1055","sc":1,"sum":"The Court determined that language in the federal charter of the Federal National Mortgage Association (Fannie Mae) that authorizes the organization to sue and be sued does not mean that federal courts have subject matter jurisdiction over any case in which Fannie Mae is a plaintiff or defendant, and the Supreme Court’s precedent in American National Red Cross v. S.G. doe not require a different result.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"NCAA v. Smith","cite":"525 U.S. 459","y":1999,"id":"1998/98-84","sc":1,"sum":"The Court held that dues payments from recipients of federal funds do not suffice to subject the NCAA to suit under Title IX.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Raymond B. Yates, M.D., P.C. Profit Sharing Plan v. Hendon","cite":"541 U.S. 1","y":2004,"id":"2003/02-458","sc":1,"sum":"The Court reasoned that this was the intent of Congress and that the act's text verifies this. In a business in which an ERISA plan covers employees, the employer can essentially qualify as an employee and receive the plan's protections. In light of this, the Court sent Yates' bankruptcy issues to a lower court for resolution.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Smith v. Robinson","cite":"468 U.S. 992","y":1984,"id":"1983/82-2120","sc":1,"sum":"When the Superintendent of Schools in Cumberland, R. I., informed petitioner parents of petitioner child, who suffers from cerebral palsy and other handicaps, that the School Committee no longer would fund the child's placement in a special educational program, the parents, in addition to appealing the Superintendent's decision to the School Committee and thereafter through the state administrative process, filed an …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Sobel v. Yeshiva Univ.","cite":"477 F. Supp. 1161","y":1979,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./477/1161/","by":{"2":"28"}},{"t":"case","label":"Storey v. Board of Regents of Univ. of Wisconsin Sys.","cite":"604 F. Supp. 1200","y":1985,"court":"W.D. Wis.","url":"https://www.courtlistener.com/c/F.%20Supp./604/1200/","by":{"2":"28"}},{"t":"case","label":"United States v. Tohono O’odham Nation","cite":"563 U.S. 307","y":2011,"id":"2010/09-846","sc":1,"sum":"The Court held that the Court of Federal Claims lacked jurisdiction to hear a suit against the federal government about a claim already being litigated against the government in another court, even when the lawsuits seek different relief based on the same set of facts.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"usc","label":"42 U.S.C. § 2000e-1","url":"https://www.law.cornell.edu/uscode/text/42/2000e-1","subs":["(1964)","(1976)"],"by":{"2":"6, 6, 6"}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","by":{"2":"6"}},{"t":"usc","label":"20 U.S.C. § 1687","url":"https://www.law.cornell.edu/uscode/text/20/1687","by":{"2":"29"}},{"t":"law","label":"Pub. L. No. 99-506","url":"https://www.govinfo.gov/link/statute/100/1845","by":{"2":"7"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(b)"],"by":{"2":"8"}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","subs":["(b)"],"by":{"2":"6"}},{"t":"case","label":"Atascadero State Hosp. v. Scanlon","cite":"473 U.S. 234","y":1985,"id":"1984/84-351","sc":1,"sum":"Respondent's action is proscribed by the Eleventh Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"16"}},{"t":"case","label":"Cent. Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"City of Rancho Palos Verdes v. Abrams","cite":"544 U.S. 113","y":2005,"id":"2004/03-1601","sc":1,"sum":"The Court held that Abrams could not enforce the limitations of the Telecommunications Act on local authorities through federal liability law, because the act provides its own judicial remedy. Congress could not have meant the judicial remedy expressly authorized by the Telecommunications Act to co-exist with an alternative remedy.","sumSrc":"Oyez","by":{"3":"25"}},{"t":"case","label":"Comcast Corp. v. Nat’l Ass’n of Afr. Am.-Owned Media","cite":"589 U.S. 327","y":2020,"url":"https://supreme.justia.com/cases/federal/us/589/327/","sc":1,"by":{"3":"12"}},{"t":"case","label":"Corr. Servs. Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"sum":"The Court held that Bivens' limited holding may not be extended to confer a right of action for damages against private entities acting under color of federal law. The Court reasoned that the threat of suit against an individual's employer was not the kind of deterrence contemplated by the Bivens decision.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"Lane v. Pena","cite":"518 U.S. 187","y":1996,"id":"1995/95-365","sc":1,"sum":"Although the related provisions of the 1973 Rehabilitation Act and the 1991 Civil Rights Act might in combination be read as waiving the federal government's sovereign immunity, absent an unambiguous waiver of sovereign immunity, the court cannot permit damages to be awarded.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Ledbetter v. Goodyear Tire & Rubber Co.","cite":"550 U.S. 618","y":2007,"id":"2006/05-1074","sc":1,"sum":"The Court ruled that a plaintiff cannot bring a salary discrimination suit under Title VII of the Civil Rights Act when the disparate pay is the result of decisions made outside of the 180-day limitations period.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Lomax v. Ortiz-Marquez","cite":"590 U.S. 595","y":2020,"id":"2019/18-8369","sc":1,"sum":"The Court held that a dismissal without prejudice for failure to state a claim counts as a strike under the Prison Litigation Reform Act, 28 U.S.C. § 1915(g), which bars inmates from filing or appealing a federal civil action without paying the associated fees if they have filed three or more cases or appeals that were dismissed because the lawsuits were frivolous or malicious or did not properly state a legal claim for relief.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Rural Hous. Serv. v. Kirtz","cite":"601 U.S. 42","y":2024,"id":"2023/22-846","sc":1,"sum":"A consumer may sue a federal agency under 15 U. S. C. §§1681n and 1681o for defying the terms of the Fair Credit Reporting Act.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"23, 24"}},{"t":"reg","label":"34 C.F.R. § 106.41","url":"https://www.ecfr.gov/current/title-34/section-106.41","by":{"3":"27"}}]};